p = 'internal/snapshot/snapshot.go'
s = open(p).read()
start = s.index('// Version 1 (Tally 0.x)')
head = '''// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded, and Upgrade rewrites
// them in place. Save replaces the file atomically, so a crash leaves either the old snapshot or the new one.
package snapshot

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes. Version 3 numbers the invoices and keeps each organization's next invoice number.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version this package cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

// file is the layout of versions 2 and 3. Version 3 adds the invoice numbers and the next numbers, in the state.
type file struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path. The file is written to a temporary file in the same folder, which replaces path
// once it is complete.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := encode(st.Export(), now)
	if err != nil {
		return err
	}
	return writeFileAtomic(path, b)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	st, _, err := decode(b)
	if err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	s, err := store.FromState(st)
	if err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	return s, nil
}

// Upgrade rewrites the snapshot at path as version 3. Before that, the original is copied byte for byte to
// "<path>.v<old version>.bak", for example tally.json.v2.bak. A version 3 file is left alone, without a backup. A file of a
// newer version fails with ErrUnsupportedVersion and is not touched.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	st, version, err := decode(b)
	if err != nil {
		return fmt.Errorf("snapshot %s: %w", path, err)
	}
	if version == Version {
		return nil
	}
	// Number the invoices and check the state the way Load would before anything is written.
	s, err := store.FromState(st)
	if err != nil {
		return fmt.Errorf("snapshot %s: %w", path, err)
	}
	if err := writeBackup(fmt.Sprintf("%s.v%d.bak", path, version), b); err != nil {
		return err
	}
	out, err := encode(s.Export(), time.Now())
	if err != nil {
		return err
	}
	return writeFileAtomic(path, out)
}

// decode reads a snapshot of any version this package reads, and returns its state and version. The invoices of a version
// 1 or 2 snapshot have no numbers; store.FromState gives them some.
func decode(b []byte) (store.State, int, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return store.State{}, 0, err
	}
	switch head.Version {
	case 1:
		st, err := migrateV1(b)
		if err != nil {
			return store.State{}, 1, fmt.Errorf("version 1: %w", err)
		}
		return st, 1, nil
	case 2, 3:
		var f file
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, head.Version, err
		}
		return f.State, head.Version, nil
	}
	return store.State{}, head.Version, fmt.Errorf("%w %d", ErrUnsupportedVersion, head.Version)
}

func encode(st store.State, now time.Time) ([]byte, error) {
	b, err := json.MarshalIndent(file{Version: Version, SavedAt: now.UTC(), State: st}, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\\n'), nil
}

// writeFileAtomic replaces path with data. It writes a temporary file beside path, flushes it to disk and renames it over
// path, so that path is always either the old file or the whole new one. The temporary file is removed on failure.
func writeFileAtomic(path string, data []byte) (err error) {
	f, err := os.CreateTemp(filepath.Dir(path), filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = f.Close()
			_ = os.Remove(f.Name())
		}
	}()
	if _, err := f.Write(data); err != nil {
		return err
	}
	if err := f.Sync(); err != nil {
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	if err := os.Rename(f.Name(), path); err != nil {
		return err
	}
	// Make the rename itself durable. Not every platform can sync a directory, so the error is ignored.
	if d, err := os.Open(filepath.Dir(path)); err == nil {
		_ = d.Sync()
		_ = d.Close()
	}
	return nil
}

// writeBackup writes the original bytes of an upgraded snapshot to path. A backup that already holds the same bytes, from an
// upgrade that was interrupted, is kept; a different one is not overwritten.
func writeBackup(path string, b []byte) error {
	old, err := os.ReadFile(path)
	switch {
	case err == nil && bytes.Equal(old, b):
		return nil
	case err == nil:
		return fmt.Errorf("backup %s already exists and differs from the snapshot; move it aside and retry", path)
	case !errors.Is(err, fs.ErrNotExist):
		return err
	}
	return writeFileAtomic(path, b)
}

'''
open(p, 'w').write(head + s[start:])
EOF
