func TestUpgradeVersion2(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	orig := readTestdata(t, "v2.json")
	writeFile(t, path, orig)

	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if bak := readFile(t, path+".v2.bak"); !bytes.Equal(bak, orig) {
		t.Fatal("the backup is not a copy of the original")
	}
	if v := version(t, path); v != 3 {
		t.Fatalf("version after the upgrade = %d", v)
	}
	before, err := Load(filepath.Join("testdata", "v2.json"))
	if err != nil {
		t.Fatal(err)
	}
	after, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(after.Export(), before.Export()) {
		t.Fatal("the upgrade changed the data")
	}

	if err := Upgrade(path); err != nil {
		t.Fatalf("upgrading a version 3 file: %v", err)
	}
	assertFiles(t, dir, "tally.json", "tally.json.v2.bak")
}

