func TestLoadVersion2NumbersInvoicesInCreationOrder(t *testing.T) {
	st, err := Load(filepath.Join("testdata", "v2.json"))
	if err != nil {
		t.Fatal(err)
	}
	// Per organization, by created_at and then ID: in_000005 and in_000006 were created at the same time, in_000003 later.
	want := []struct{ org, id, number string }{
		{"org_000001", "in_000005", "INV-000001"},
		{"org_000001", "in_000006", "INV-000002"},
		{"org_000001", "in_000003", "INV-000003"},
		{"org_000002", "in_000004", "INV-000001"},
	}
	for _, w := range want {
		inv, ok := st.Invoice(w.org, w.id)
		if !ok || inv.Number != w.number {
			t.Fatalf("invoice %s = %+v, want number %s", w.id, inv, w.number)
		}
	}
	next, err := st.CreateInvoice(store.Invoice{OrgID: "org_000001", CustomerID: "cus_000007", Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, time.Now())
	if err != nil || next.Number != "INV-000004" {
		t.Fatalf("next invoice = %+v, %v", next, err)
	}
	other, err := st.CreateInvoice(store.Invoice{OrgID: "org_000002", CustomerID: "cus_000008", Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, time.Now())
	if err != nil || other.Number != "INV-000002" {
		t.Fatalf("the other organization's next invoice = %+v, %v", other, err)
	}
}

func readTestdata(t *testing.T, name string) []byte {
	t.Helper()
	return readFile(t, filepath.Join("testdata", name))
}

func readFile(t *testing.T, path string) []byte {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func writeFile(t *testing.T, path string, b []byte) {
	t.Helper()
	if err := os.WriteFile(path, b, 0o600); err != nil {
		t.Fatal(err)
	}
}

func version(t *testing.T, path string) int {
	t.Helper()
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(readFile(t, path), &head); err != nil {
		t.Fatal(err)
	}
	return head.Version
}

// assertFiles checks that dir holds exactly the named files, so no temporary file was left behind.
func assertFiles(t *testing.T, dir string, names ...string) {
	t.Helper()
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	var got []string
	for _, e := range entries {
		got = append(got, e.Name())
	}
	if !reflect.DeepEqual(got, names) {
		t.Fatalf("files in %s = %v, want %v", dir, got, names)
	}
}
